import TjProductCard from "../components/TjProductCard.vue";

export default {
  components: {
    TjButton: TjButton,
    TjProductCard,
  },
  props: {
    modelName: {
      type: String,
      default: "",
    },
  },
  computed: {
    product() {
      return getProductDetail(this.modelName);
    },
    storeProduct() {
      return getStoreProduct(this.modelName);
